const fs=require('fs'),path=require('path'),assert=require('assert/strict');const {chromium}=require('C:/Users/Seba/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');(async()=>{const root=path.resolve(__dirname,'..'),pages=['index.html','product.html','stories/index.html','prototype.html','delivery.html','qa.html',...Array.from({length:5},(_,i)=>`stories/us${i+1}.html`)];const b=await chromium.launch({headless:true,channel:'msedge'}),p=await b.newPage({javaScriptEnabled:false}),ids={},links=[];for(const file of pages){await p.goto('file:///'+path.join(root,file).replaceAll('\\','/'));const data=await p.evaluate(()=>({ids:[...document.querySelectorAll('[id]')].map(x=>x.id),links:[...document.querySelectorAll('a[href],script[src],link[href],img[src]')].map(x=>x.getAttribute('href')||x.getAttribute('src'))}));assert.equal(new Set(data.ids).size,data.ids.length);ids[file]=new Set(data.ids);for(const link of data.links)links.push([file,link]);if(file==='stories/index.html'){await p.setViewportSize({width:390,height:844});assert.equal(await p.locator('.story-tabs a:visible').count(),5)}}for(const [file,link]of links){if(/^(https?:|data:)/.test(link))continue;const [f,hash]=link.split('#'),dest=f?path.posix.normalize(path.posix.join(path.posix.dirname(file),f)):file;assert.ok(fs.existsSync(path.join(root,dest)),file+' -> '+link);if(hash&&ids[dest])assert.ok(ids[dest].has(hash),file+' -> '+link)}await b.close();console.log('PASS 11 file-based pages, no-JavaScript fallback, unique IDs and '+links.length+' links');fs.writeFileSync(path.join(root,'evidence/links.json'),JSON.stringify({result:'PASS',pages:11,links:links.length},null,2));})();
